function(container, tables) {
    // 外部要因データ管理の初期化
    const weatherDataBtn = container.querySelector('#weatherDataBtn');
    const eventDataBtn = container.querySelector('#eventDataBtn');
    const seasonalDataBtn = container.querySelector('#seasonalDataBtn');
    const correlationAnalysisBtn = container.querySelector('#correlationAnalysisBtn');
    const historicalComparisonBtn = container.querySelector('#historicalComparisonBtn');

    const startDateInput = container.querySelector('#startDate');
    const endDateInput = container.querySelector('#endDate');
    const regionSelect = container.querySelector('#regionSelect');
    const factorTypeSelect = container.querySelector('#factorType');

    const weatherDataTable = container.querySelector('#weatherDataTable tbody');
    const eventDataTable = container.querySelector('#eventDataTable tbody');
    const seasonalDataTable = container.querySelector('#seasonalDataTable tbody');
    const correlationResultsDiv = container.querySelector('#correlationResults');
    const comparisonResultsDiv = container.querySelector('#comparisonResults');

    // 業務ロジックモジュールをインポート
    const { 
        collectWeatherData, 
        collectEventData, 
        collectSeasonalData, 
        analyzeCorrelationSalesWeather, 
        analyzeCorrelationSalesEvent, 
        analyzeCorrelationSalesSeason, 
        compareWithHistoricalData,
        collectSalesData
    } = window.aivicLogic.ai;

    // 天候データ収集
    if (weatherDataBtn) {
        weatherDataBtn.addEventListener('click', async () => {
            try {
                const startDate = startDateInput?.value;
                const endDate = endDateInput?.value;
                const region = regionSelect?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                const weatherData = await collectWeatherData(startDate, endDate, region);

                if (weatherDataTable) {
                    weatherDataTable.innerHTML = '';
                    weatherData.forEach(data => {
                        const row = document.createElement('tr');
                        row.innerHTML = `
                            <td>${data.date}</td>
                            <td>${data.temperature}°C</td>
                            <td>${data.humidity}%</td>
                            <td>${data.weather}</td>
                            <td>${data.region}</td>
                        `;
                        weatherDataTable.appendChild(row);
                    });
                }

                window.aivicNotify.success('天候データを取得しました');
            } catch (error) {
                window.aivicNotify.error('天候データの取得に失敗しました: ' + error.message);
            }
        });
    }

    // イベントデータ収集
    if (eventDataBtn) {
        eventDataBtn.addEventListener('click', async () => {
            try {
                const startDate = startDateInput?.value;
                const endDate = endDateInput?.value;
                const region = regionSelect?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                const eventData = await collectEventData(startDate, endDate, region);

                if (eventDataTable) {
                    eventDataTable.innerHTML = '';
                    eventData.forEach(data => {
                        const row = document.createElement('tr');
                        row.innerHTML = `
                            <td>${data.date}</td>
                            <td>${data.eventName}</td>
                            <td>${data.eventType}</td>
                            <td>${data.impact}</td>
                            <td>${data.region}</td>
                        `;
                        eventDataTable.appendChild(row);
                    });
                }

                window.aivicNotify.success('イベントデータを取得しました');
            } catch (error) {
                window.aivicNotify.error('イベントデータの取得に失敗しました: ' + error.message);
            }
        });
    }

    // 季節データ収集
    if (seasonalDataBtn) {
        seasonalDataBtn.addEventListener('click', async () => {
            try {
                const startDate = startDateInput?.value;
                const endDate = endDateInput?.value;
                const region = regionSelect?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                const seasonalData = await collectSeasonalData(startDate, endDate, region);

                if (seasonalDataTable) {
                    seasonalDataTable.innerHTML = '';
                    seasonalData.forEach(data => {
                        const row = document.createElement('tr');
                        row.innerHTML = `
                            <td>${data.date}</td>
                            <td>${data.season}</td>
                            <td>${data.factor}</td>
                            <td>${data.value}</td>
                            <td>${data.region}</td>
                        `;
                        seasonalDataTable.appendChild(row);
                    });
                }

                window.aivicNotify.success('季節データを取得しました');
            } catch (error) {
                window.aivicNotify.error('季節データの取得に失敗しました: ' + error.message);
            }
        });
    }

    // 相関分析
    if (correlationAnalysisBtn) {
        correlationAnalysisBtn.addEventListener('click', async () => {
            try {
                const startDate = startDateInput?.value;
                const endDate = endDateInput?.value;
                const region = regionSelect?.value;
                const factorType = factorTypeSelect?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                if (!factorType) {
                    window.aivicNotify.error('要因タイプを選択してください');
                    return;
                }

                // 売上データを取得
                const salesData = await collectSalesData(startDate, endDate);
                let correlationResult;

                // 要因タイプに応じて相関分析を実行
                switch (factorType) {
                    case 'weather':
                        const weatherData = await collectWeatherData(startDate, endDate, region);
                        correlationResult = analyzeCorrelationSalesWeather(salesData, weatherData);
                        break;
                    case 'event':
                        const eventData = await collectEventData(startDate, endDate, region);
                        correlationResult = analyzeCorrelationSalesEvent(salesData, eventData);
                        break;
                    case 'seasonal':
                        const seasonalData = await collectSeasonalData(startDate, endDate, region);
                        correlationResult = analyzeCorrelationSalesSeason(salesData, seasonalData);
                        break;
                    default:
                        throw new Error('無効な要因タイプです');
                }

                if (correlationResultsDiv) {
                    correlationResultsDiv.innerHTML = `
                        <h4>相関分析結果</h4>
                        <p>相関係数: ${correlationResult.correlation.toFixed(3)}</p>
                        <p>決定係数: ${correlationResult.rSquared.toFixed(3)}</p>
                        <p>有意性: ${correlationResult.significance}</p>
                        <div class="correlation-details">
                            ${correlationResult.details.map(detail => 
                                `<p>${detail.factor}: ${detail.impact}</p>`
                            ).join('')}
                        </div>
                    `;
                }

                window.aivicNotify.success('相関分析が完了しました');
            } catch (error) {
                window.aivicNotify.error('相関分析に失敗しました: ' + error.message);
            }
        });
    }

    // 過去データ比較
    if (historicalComparisonBtn) {
        historicalComparisonBtn.addEventListener('click', async () => {
            try {
                const startDate = startDateInput?.value;
                const endDate = endDateInput?.value;
                const region = regionSelect?.value;

                if (!startDate || !endDate) {
                    window.aivicNotify.error('開始日と終了日を入力してください');
                    return;
                }

                // 現在期間のデータを取得
                const currentSalesData = await collectSalesData(startDate, endDate);
                const currentWeatherData = await collectWeatherData(startDate, endDate, region);
                const currentEventData = await collectEventData(startDate, endDate, region);

                // 過去データとの比較を実行
                const comparisonResult = await compareWithHistoricalData(
                    currentSalesData,
                    currentWeatherData,
                    currentEventData,
                    startDate,
                    endDate
                );

                if (comparisonResultsDiv) {
                    comparisonResultsDiv.innerHTML = `
                        <h4>過去データ比較結果</h4>
                        <div class="comparison-summary">
                            <p>売上変化率: ${comparisonResult.salesChangeRate.toFixed(2)}%</p>
                            <p>天候類似度: ${comparisonResult.weatherSimilarity.toFixed(3)}</p>
                            <p>イベント影響度: ${comparisonResult.eventImpact.toFixed(3)}</p>
                        </div>
                        <div class="comparison-details">
                            <h5>詳細分析</h5>
                            ${comparisonResult.insights.map(insight => 
                                `<p>• ${insight}</p>`
                            ).join('')}
                        </div>
                        <div class="recommendations">
                            <h5>推奨事項</h5>
                            ${comparisonResult.recommendations.map(rec => 
                                `<p>• ${rec}</p>`
                            ).join('')}
                        </div>
                    `;
                }

                window.aivicNotify.success('過去データ比較が完了しました');
            } catch (error) {
                window.aivicNotify.error('過去データ比較に失敗しました: ' + error.message);
            }
        });
    }

    // 初期データ読み込み
    const loadInitialData = async () => {
        try {
            // 地域選択肢を設定
            if (regionSelect) {
                const regions = ['全国', '北海道', '東北', '関東', '中部', '関西', '中国', '四国', '九州'];
                regionSelect.innerHTML = regions.map(region => 
                    `<option value="${region}">${region}</option>`
                ).join('');
            }

            // 要因タイプ選択肢を設定
            if (factorTypeSelect) {
                const factorTypes = [
                    { value: 'weather', label: '天候' },
                    { value: 'event', label: 'イベント' },
                    { value: 'seasonal', label: '季節' }
                ];
                factorTypeSelect.innerHTML = factorTypes.map(type => 
                    `<option value="${type.value}">${type.label}</option>`
                ).join('');
            }

            // デフォルト日付を設定
            if (startDateInput && endDateInput) {
                const today = new Date();
                const oneMonthAgo = new Date(today.getFullYear(), today.getMonth() - 1, today.getDate());

                startDateInput.value = oneMonthAgo.toISOString().split('T')[0];
                endDateInput.value = today.toISOString().split('T')[0];
            }

        } catch (error) {
            window.aivicNotify.error('初期データの読み込みに失敗しました: ' + error.message);
        }
    };

    // 初期化実行
    loadInitialData();
}
